import {abilityScore,TRUE_REQUIREMENTS,TRUE_RESEARCH_REQUIREMENTS,degreeRequirements,careerScores,recommendationCandidate} from './engine.js';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={learning:'학습',research:'연구수행',language:'어학·전달',social:'의사소통',autonomy:'자율성',teaching:'교육 경험',rapport:'라포',resilience:'정신력',manners:'예의범절',motivation:'의욕',submissions:'논문 제출',papers:'논문 게재',conferences:'학술 발표',recommendations:'추천서',faculty:'교수 업무 최저값'};
export function endingEvidence(s){
 if(!s.ending)return null;
 const metrics=[{label:'지도기간(개월)',value:s.month},{label:'논문 게재',value:s.career.papers},{label:'학술 발표',value:s.career.conferences},{label:'수상',value:s.career.awards},{label:'h-index',value:s.impact?.hIndex??0},{label:'라포(0–100)',value:abilityScore(s,'rapport')}];
 if(['true','postdoc'].includes(s.ending))for(const [key,target] of Object.entries(TRUE_REQUIREMENTS))metrics.push({label:labels[key],value:key==='faculty'?Math.min(...Object.values(s.professor)):key in s.hidden?abilityScore(s,key):s.career[key],target});
 if(['true','postdoc'].includes(s.ending))metrics.push({label:'선도 논문',value:s.career.topPapers,target:TRUE_RESEARCH_REQUIREMENTS.leadingPaper},{label:'h-index 임용 준비 기준',value:s.impact?.hIndex??0,target:TRUE_RESEARCH_REQUIREMENTS.hIndex});
 else {for(const key of ['research','language','autonomy','industry','enterprise'])metrics.push({label:labels[key]??({industry:'산학 경험',enterprise:'창업 경험'})[key],value:abilityScore(s,key)});const score=careerScores(s)[s.ending];if(score>=0)metrics.push({label:'진로 적합도(게임 지표)',value:score});}
 if(s.ending==='resident_researcher')metrics.push({label:'신중함 · 안정 선호(게임 기질)',value:s.temperament.caution,target:65},{label:'연구실 운영',value:s.professor.mentoring,target:40});
 const requirements=['bachelor','external_masters'].includes(s.ending)?{}:degreeRequirements(s,['masters','external_phd'].includes(s.ending)?'masters':'phd');
 return {metrics,requirements:Object.entries(requirements).map(([key,target])=>({label:labels[key]??key,value:s.career[key],target})).filter(r=>Number.isFinite(r.value)),reason:s.endingReason??null,recommendation:recommendationCandidate(s)?abilityScore(s,'rapport')>=TRUE_REQUIREMENTS.rapport?'strong':abilityScore(s,'rapport')>=40?'formal':'alternate':null};
}
export function validEvidence(e){const rows=x=>Array.isArray(x)&&x.length<=30&&x.every(r=>r&&Object.keys(r).every(k=>['label','value','target'].includes(k))&&typeof r.label==='string'&&r.label.length<=80&&Number.isFinite(r.value)&&r.value>=0&&r.value<=100000&&(r.target===undefined||Number.isFinite(r.target)&&r.target>=0&&r.target<=100000));return e&&Object.keys(e).every(k=>['metrics','requirements','reason','recommendation'].includes(k))&&(e.recommendation===undefined||e.recommendation===null||['strong','formal','alternate'].includes(e.recommendation))&&rows(e.metrics)&&rows(e.requirements)&&(e.reason===null||typeof e.reason==='string'&&e.reason.length<=80);}
export function renderEvidence(e){if(!validEvidence(e))return '';return `<section class="ending-evidence"><h3>엔딩 판정 · 수치 기록</h3><p>종료 시점의 게임 상태를 보관한 기록입니다. 실제 진로의 확률이나 사람에 대한 평가는 아닙니다.</p>${e.recommendation?`<p>마감 사흘 전 추천서 부탁: ${({strong:'구체적으로 검토해 다음 날 발송',formal:'형식적인 추천서를 마감 당일 발송',alternate:'다른 추천인에게 요청'})[e.recommendation]}</p>`:''}<table><thead><tr><th>지표</th><th>종료값</th><th>기준</th></tr></thead><tbody>${e.metrics.map(r=>`<tr><th scope="row">${escape(r.label)}</th><td>${Number.isInteger(r.value)?r.value:r.value.toFixed(2)}</td><td>${r.target===undefined?'—':r.target}</td></tr>`).join('')}</tbody></table></section>`;}
